"""Serial event-transport adaptation of the cached partial gather barrier.

The barrier owns, per endpoint (worker):

* the last accepted raw edge load row (`storage[w]`) - a TOTAL, not a mean,
* the cached path amounts of the commodities that endpoint owns,
* whether the endpoint has ever been seen, whether its last accepted result is
  still fresh, the round that acceptance happened on (age) and the ticket
  sequence number that produced it (staleness / superseding).

A step may advance only when every endpoint answered at least once, at least
`min_arrival` distinct endpoints are fresh and no seen endpoint has an age
beyond `max_lag` (equality with `max_lag` is allowed).
"""
import numpy as np


class PartialBarrier:

    def __init__(self, number_of_endpoints, min_arrival, max_lag, num_edges):
        self._number_of_endpoints = number_of_endpoints
        self._min_arrival = min_arrival if min_arrival is not None else number_of_endpoints
        self._max_lag = max_lag
        self._num_edges = num_edges
        self._clock = 0
        self._storage = np.zeros((number_of_endpoints, num_edges))
        self._amounts = {}
        self._arrival_set = set()
        self._initial_response_set = set(range(number_of_endpoints))
        self._last_response = [None] * number_of_endpoints
        self._last_sequence = [None] * number_of_endpoints

    # ------------------------------------------------------------------ state
    @property
    def clock(self):
        return self._clock

    @property
    def storage(self):
        return self._storage

    @property
    def arrivals(self):
        return self._arrival_set

    @property
    def endpoints(self):
        return range(self._number_of_endpoints)

    @property
    def last_sequence(self):
        return self._last_sequence

    def seen(self):
        """Endpoints with at least one accepted result since the last reset."""
        return sorted(set(self.endpoints) - self._initial_response_set)

    def unseen(self):
        return sorted(self._initial_response_set)

    def fresh(self):
        return sorted(self._arrival_set)

    def ages(self):
        out = []
        for w in self.endpoints:
            last = self._last_response[w]
            out.append(None if last is None else self._clock - last)
        return out

    def stale(self):
        return [w for w in self.endpoints
                if self._last_response[w] is not None
                and self._clock - self._last_response[w] > self._max_lag]

    def blockers(self):
        """`(missing, stale)`: the reasons a step cannot advance."""
        return self.unseen(), self.stale()

    def can_advance(self):
        if self.unseen():
            return False
        if len(self._arrival_set) < self._min_arrival:
            return False
        return not self.stale()

    def first_response_pending(self):
        return bool(self._initial_response_set)

    # ----------------------------------------------------------------- events
    def arrive(self, node_id, response, sequence, amounts=None):
        """Record an accepted result: it replaces this endpoint's whole cache."""
        self._storage[node_id, :] = np.asarray(response, dtype=np.float64)
        self._amounts[node_id] = amounts
        self._initial_response_set.discard(node_id)
        self._arrival_set.add(node_id)
        self._last_response[node_id] = self._clock
        self._last_sequence[node_id] = sequence

    def superseded(self, node_id, sequence):
        """True when a later-issued ticket of this endpoint was accepted."""
        last = self._last_sequence[node_id]
        return last is not None and sequence < last

    def advance(self):
        """Round counter plus one, freshness cleared, cached data persists."""
        self._clock += 1
        self._arrival_set.clear()

    def reset(self):
        self._clock = 0
        self._arrival_set.clear()
        self._initial_response_set = set(range(self._number_of_endpoints))
        self._last_response = [None] * self._number_of_endpoints
        self._last_sequence = [None] * self._number_of_endpoints
        self._storage = np.zeros((self._number_of_endpoints, self._num_edges))
        self._amounts = {}

    # ------------------------------------------------------------- checkpoints
    def state(self):
        return {'clock': self._clock,
                'arrival': set(self._arrival_set),
                'responded': set(range(self._number_of_endpoints)) - set(self._initial_response_set),
                'last_response': list(self._last_response),
                'last_sequence': list(self._last_sequence),
                'storage': self._storage.copy(),
                'amounts': dict(self._amounts)}

    def load_state(self, saved):
        self._clock = saved['clock']
        self._arrival_set = set(saved['arrival'])
        self._initial_response_set = set(range(self._number_of_endpoints)) - set(saved['responded'])
        self._last_response = list(saved['last_response'])
        self._last_sequence = list(saved['last_sequence'])
        self._storage = saved['storage'].copy()
        self._amounts = dict(saved['amounts'])
