"""CPU consensus state; acceleration variants are outside this offline profile."""
import enum, math
import numpy as np
from typing import Optional, Dict
from array_utils.cpu.types import *


class ADMMMode(str, enum.Enum):
    VANILLA = 'Vanilla'
    ACCELERATED = 'Accelerated'
    OVER_RELAXED = 'Over-Relaxed'
    ACCELERATED_OVER_RELAXED = 'Accelerated-Over-Relaxed'


class ADMMWrapper:
    """Consensus variables of the outer sharing loop.

    `Z` is the consensus vector (controller `z`) and `dual_var` is the SCALED
    dual (`u`).  With an `alpha` relaxation the primal average seen by the
    controller is `alpha * X + (1 - alpha) * Z_old`, which is exactly the
    argument of the controller proximation step, and the scaled dual advances
    by that same relaxed residual.
    """

    def __init__(self, n: int, rho: float, A: Optional[CPUArray]=None, B: Optional[CPUArray]=None,
                 C: Optional[CPUArray]=None, alpha: Optional[float]=None, nesterov: bool=False,
                 nesterov_coeff: Optional[float]=None, adaptive_mu: Optional[float]=None,
                 adaptive_tau: Optional[float]=None, adaptive_T: Optional[int]=None):
        if alpha is None:
            self._mode: ADMMMode = ADMMMode.VANILLA if nesterov is False else ADMMMode.ACCELERATED
        elif nesterov is False:
            self._mode: ADMMMode = ADMMMode.OVER_RELAXED
        else:
            self._mode: ADMMMode = ADMMMode.ACCELERATED_OVER_RELAXED
        self._n = n
        self._rho_start = rho
        self._rho = rho
        self._A = A
        self._B = B
        self._C = C
        self._alpha = 1.0 if alpha is None else float(alpha)
        self._nu: float = 1
        if nesterov_coeff is not None:
            self._nesterov_coeff: float = nesterov_coeff
            self._nesterov_coeff_auto = False
        else:
            self._nesterov_coeff_auto = True
        self._dual_var: Optional[CPUArray] = None
        self._dual_var_old: Optional[CPUArray] = None
        self._dual_var_nesterov: Optional[CPUArray] = None
        self._X: Optional[CPUArray] = None
        self._Z: Optional[CPUArray] = None
        self._Z_old: Optional[CPUArray] = None
        self._Z_nesterov: Optional[CPUArray] = None
        is_adaptive = adaptive_mu is not None and adaptive_tau is not None and (adaptive_T is not None)
        assert is_adaptive ^ (adaptive_mu is None and adaptive_tau is None and (adaptive_T is None)), \
            'Either all `adaptive_...` parameters must be given, or none of them!'
        if is_adaptive:
            assert adaptive_T >= 1 and adaptive_mu >= 1 and (adaptive_tau >= 1)
        self._is_adaptive = is_adaptive
        self._adaptive_mu = adaptive_mu
        self._adaptive_tau = adaptive_tau
        self._adaptive_T = adaptive_T
        self._iterate: int = 0
        self._pinf_dict: Dict[int, float] = dict()
        self._dinf_dict: Dict[int, float] = dict()
        self._adapt_tokens = 0

    def initialize(self, X_start: CPUArray, Z_start: Optional[CPUArray]=None):
        self._X = cpu_array(X_start)
        self._Z = cpu_array(X_start) if Z_start is None else cpu_array(Z_start)
        self._Z_old = cpu_array(self._Z)
        self._Z_nesterov = cpu_array(self._Z)
        self._dual_var = cpu_zeros((self._n,))
        self._dual_var_old = cpu_zeros((self._n,))
        self._dual_var_nesterov = cpu_zeros((self._n,))
        self._iterate = 0

    @property
    def mode(self) -> ADMMMode:
        return self._mode

    @property
    def dual_var(self) -> CPUArray:
        assert self._dual_var is not None
        return self._dual_var

    @property
    def X(self) -> CPUArray:
        assert self._X is not None
        return self._X

    @property
    def X_old(self) -> CPUArray:
        assert self._X is not None
        return self._X

    @property
    def Z(self) -> CPUArray:
        assert self._Z is not None
        return self._Z

    @property
    def Z_old(self) -> CPUArray:
        assert self._Z is not None
        return self._Z if self._Z_old is None else self._Z_old

    @property
    def alpha(self) -> float:
        return self._alpha

    @property
    def step_size(self) -> float:
        return self._rho

    @step_size.setter
    def step_size(self, value: float):
        self._rho = float(value)

    def retune(self, rho: float):
        """Change the penalty, keeping the unscaled dual `rho * u` invariant."""
        old = float(self._rho)
        new = float(rho)
        if new == old:
            return
        if self._dual_var is not None:
            self._dual_var = self._dual_var * (old / new)
        self._rho = new

    def _mul_A(self, thing: CPUArray, over_relax: bool) -> CPUArray:
        if over_relax and self._A is not None:
            return self._alpha * self._A @ thing
        elif over_relax and self._A is None:
            return self._alpha * thing
        elif not over_relax and self._A is not None:
            return self._A @ thing
        return thing

    def _mul_B(self, thing: CPUArray, over_relax: bool) -> CPUArray:
        if over_relax and self._B is not None:
            return (1 - self._alpha) * self._B @ thing
        elif over_relax and self._B is None:
            return -(1 - self._alpha) * thing
        elif not over_relax and self._B is not None:
            return self._B @ thing
        return -thing

    def _add_C(self, thing: CPUArray, over_relax: bool) -> CPUArray:
        if self._C is not None:
            if over_relax:
                return self._alpha * self._C + thing
            return self._C + thing
        return thing

    def relaxed_primal(self, next_X: CPUArray) -> CPUArray:
        """`alpha * X + (1 - alpha) * Z_old` - the controller's reference point."""
        a = self._alpha
        return a * np.asarray(next_X, dtype=np.float64) + (1.0 - a) * self.Z_old

    def get_X_step_bias(self) -> CPUArray:
        """Worker side target: `Z - u` (the consensus point minus the scaled dual)."""
        return self.Z - self._dual_var

    def get_Z_step_bias(self, next_X: Optional[CPUArray] = None) -> CPUArray:
        """Controller side reference: the relaxed primal plus the scaled dual."""
        X = self._X if next_X is None else np.asarray(next_X, dtype=np.float64)
        return self.relaxed_primal(X) + self._dual_var

    def record_X_update(self, next_X: CPUArray):
        self._X = cpu_array(next_X)

    def record_Z_update(self, next_Z: CPUArray):
        self._Z_old = cpu_array(self._Z)
        self._Z = cpu_array(next_Z)

    def _dual_var_bias(self) -> CPUArray:
        """The bias added to the controller reference: the scaled dual itself."""
        return self._dual_var

    def update_dual_var(self, next_X: Optional[CPUArray] = None,
                        next_Z: Optional[CPUArray] = None, finalize: bool = False):
        """Scaled dual ascent `u += alpha*X + (1-alpha)*Z_old - Z`."""
        X = self._X if next_X is None else np.asarray(next_X, dtype=np.float64)
        Z = self._Z if next_Z is None else np.asarray(next_Z, dtype=np.float64)
        residual = self.relaxed_primal(X) - Z
        updated = self._dual_var + residual
        self.record_dual_update(updated)
        self._iterate += 1
        return float(np.max(np.abs(residual))) if residual.size else 0.0

    def record_dual_update(self, next_dual_var: CPUArray):
        if self._mode == ADMMMode.ACCELERATED or self._mode == ADMMMode.ACCELERATED_OVER_RELAXED:
            self._dual_var_old = cpu_array(self._dual_var)
        self._dual_var = cpu_array(next_dual_var)

    # ------------------------------------------------------------- checkpoints
    def state(self):
        return {'Z': cpu_array(self._Z), 'Z_old': cpu_array(self.Z_old),
                'dual': cpu_array(self._dual_var), 'rho': self._rho,
                'iterate': self._iterate}

    def load_state(self, saved):
        self._Z = cpu_array(saved['Z'])
        self._Z_old = cpu_array(saved['Z_old'])
        self._dual_var = cpu_array(saved['dual'])
        self._rho = saved['rho']
        self._iterate = saved['iterate']
